// === Tab: mySketch ===
//created based off the Shaders tutorial by @Oren Shoham

const sketch = sketch => {

	const text = 'agency'

	let shader
	let graphics
	let font

	sketch.preload = () => {
		shader = getShader(this._renderer)
		font = sketch.loadFont('https://openprocessing.org/sketch/1157932/files/Barlow-Black.otf')
	}

	sketch.setup = () => {
		let orientation = sketch.windowWidth > sketch.windowHeight 
			? 'landscape' 
			: 'portrait'

		let size = orientation === 'portrait' 
			? sketch.windowWidth 
			: sketch.windowHeight

		sketch.createCanvas(
			sketch.windowWidth, 
			sketch.windowHeight, 
			sketch.WEBGL
		)

		sketch.noStroke()

		graphics = sketch.createGraphics(
			sketch.windowWidth,
			sketch.windowHeight
		)

		graphics.background(255,255,255)
		graphics.noStroke()
		//graphics.textFont(font)
		graphics.textSize(
			sketch.windowWidth * 0.15
		)
		graphics.textAlign(
			sketch.CENTER,
			sketch.CENTER
		)
		graphics.fill(60)
		graphics.stroke(0)
		graphics.strokeWeight(0)
		graphics.text(
			text,
			sketch.windowWidth*0.5,
			sketch.windowHeight*0.5
		)

		sketch.shader(shader)
		shader.setUniform('tex', graphics)
	}

	sketch.draw = () => {

		let freq = sketch.map(
			sketch.mouseX, 0, sketch.width, 1.5, 3.0
		)
		let amp = sketch.map(
			sketch.mouseY, 0, sketch.height, 0.15, 0.3
		)

		shader.setUniform(
			'frequency', freq
		)
		shader.setUniform(
			'amplitude', amp
		)
		shader.setUniform(
			'speed', sketch.frameCount * 0.02
		)

		sketch.rect(
			0, 0, sketch.width, sketch.height
		)

	}
}

new p5(sketch)


// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vUV;

		void main() {
			vUV = aTexCoord;

			vec4 position = vec4(aPosition, 1.0);
			position.xy = position.xy * 2.0 - 1.0;
			gl_Position = position;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vUV;

		uniform sampler2D tex;
		uniform float speed;
		uniform float frequency;
		uniform float amplitude;

		void main() {
			vec2 uv = vec2(1.0, 1.0) - vUV;
			//flip the image so its the right way around
			uv.x = uv.x * -1.0;

			// lets create a sine wave to distort our texture coords
			// we will use the built in sin() function in glsl
			// sin() returns the sine of an angle in radians
			// first will multiply our uv * frequency -- frequency will control how many hills and valleys will be in the wave
			// then we add some time to our sine, this will make it move 
			// lastly multiply the whole thing by amplitude -- amplitude controls how tall the hills and valleys are, in this case it will be how much to distort the image
			// *try changing uv.y to uv.x and see what happens

			float sineWave = sin(uv.y * frequency + speed) * amplitude;

			// create a vec2 with our sine
			// what happens if you put sineWave in the y slot? in Both slots?
			vec2 distort = vec2(sineWave, sineWave);

			// use mod() to wrap our texcoords back to 0.0 if they go over 1.0
			vec4 texColor = texture2D(tex, mod(uv - distort, 1.0));

			gl_FragColor = texColor;
		}
	`;

	return createShader(vert, frag);
}

